changeSet.sql:
ALTER TABLE log_entry ADD COLUMN model_name text; ALTER TABLE log_entry_hourly_stats ADD COLUMN model_name text;
CREATE TABLE log_entry_rollup_dirty_hours ( id bigserial PRIMARY KEY, bucket_hour timestamptz NOT NULL, enqueued_at timestamptz NOT NULL DEFAULT now() );
CREATE FUNCTION logos_model_delete_backfill_name() RETURNS trigger LANGUAGE plpgsql SET search_path = public, pg_catalog AS $$ BEGIN -- One scan: the data-modifying CTE stamps the captured name -- on every row of the model and, from the same update, -- enqueues the affected hours for the rollup. The update's -- updated_at stamp only reaches the pass while this delete -- stays shorter than the pass's write lag (see the file -- header); the queue rows commit together with the rows -- behind them, so logos_stats_rollup_pass (042) re-rolls the -- hours either way. WITH updated AS ( UPDATE log_entry SET model_name = OLD.name WHERE model_id = OLD.id RETURNING timestamp_forwarding, timestamp_request, timestamp_response ) INSERT INTO log_entry_rollup_dirty_hours (bucket_hour) SELECT DISTINCT date_trunc('hour', COALESCE(updated.timestamp_forwarding, updated.timestamp_request, updated.timestamp_response)) FROM updated WHERE COALESCE(updated.timestamp_forwarding, updated.timestamp_request, updated.timestamp_response) IS NOT NULL; RETURN OLD; END; $$;
CREATE TRIGGER trg_models_delete_backfill_model_name BEFORE DELETE ON models FOR EACH ROW EXECUTE FUNCTION logos_model_delete_backfill_name();

DROP INDEX ux_log_entry_hourly_stats_grain;
CREATE UNIQUE INDEX ux_log_entry_hourly_stats_grain ON log_entry_hourly_stats (bucket_hour, model_id, model_name, provider_id, team_id, user_id, result_status, was_cold_start) NULLS NOT DISTINCT;
CREATE OR REPLACE FUNCTION logos_stats_rollup_apply(p_hours timestamptz[]) RETURNS bigint LANGUAGE plpgsql SET search_path = public, pg_catalog AS $$ DECLARE affected bigint; BEGIN IF p_hours IS NULL OR array_length(p_hours, 1) IS NULL THEN RETURN 0; END IF;
DELETE FROM log_entry_hourly_stats s WHERE s.bucket_hour = ANY (p_hours);
INSERT INTO log_entry_hourly_stats ( bucket_hour, model_id, model_name, provider_id, team_id, user_id, result_status, was_cold_start, requests, queue_seconds_sum, queue_seconds_count, run_seconds_sum, run_seconds_count, error_count, total_tokens, cost_micro_cents) SELECT date_trunc('hour', COALESCE(le.timestamp_forwarding, le.timestamp_request, le.timestamp_response)), le.model_id, CASE WHEN le.model_id IS NULL THEN le.model_name END, le.provider_id, le.team_id, le.user_id, le.result_status, COALESCE(le.was_cold_start, FALSE), COUNT(*), SUM(CASE WHEN le.timestamp_request IS NOT NULL AND le.timestamp_forwarding IS NOT NULL THEN EXTRACT(EPOCH FROM (le.timestamp_forwarding - le.timestamp_request)) END), COUNT(*) FILTER (WHERE le.timestamp_request IS NOT NULL AND le.timestamp_forwarding IS NOT NULL), SUM(CASE WHEN le.timestamp_forwarding IS NOT NULL AND le.timestamp_response IS NOT NULL THEN EXTRACT(EPOCH FROM (le.timestamp_response - le.timestamp_forwarding)) END), COUNT(*) FILTER (WHERE le.timestamp_forwarding IS NOT NULL AND le.timestamp_response IS NOT NULL), COUNT(*) FILTER (WHERE le.result_status IS DISTINCT FROM 'success' OR (le.error_message IS NOT NULL AND le.error_message <> '')), COALESCE(SUM(tok.total_tokens), 0)::bigint, COALESCE(SUM(lec.cost_micro_cents), 0)::bigint FROM log_entry le LEFT JOIN LATERAL ( SELECT SUM(ut.token_count) AS total_tokens FROM usage_tokens ut JOIN token_types tt ON tt.id = ut.type_id WHERE ut.log_entry_id = le.id AND tt.name = 'total_tokens' ) tok ON TRUE LEFT JOIN log_entry_cost lec ON lec.log_entry_id = le.id WHERE date_trunc('hour', COALESCE(le.timestamp_forwarding, le.timestamp_request, le.timestamp_response)) = ANY (p_hours) GROUP BY 1, 2, 3, 4, 5, 6, 7, 8;
GET DIAGNOSTICS affected = ROW_COUNT; RETURN affected; END; $$;

CREATE OR REPLACE FUNCTION logos_stats_rollup_pass(p_write_lag interval)
RETURNS TABLE (hours_rebuilt bigint, rows_written bigint)
LANGUAGE plpgsql
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_last       timestamptz;
    v_cutoff     timestamptz := now() - p_write_lag;
    v_open       timestamptz := date_trunc('hour', now());
    v_hours      timestamptz[];
    v_queued     timestamptz[];
    v_queued_ids bigint[];
    v_written    bigint;
BEGIN
    SELECT processed_through INTO v_last FROM log_entry_rollup_state;
    IF v_last IS NULL THEN
        RAISE EXCEPTION 'log_entry_rollup_state is empty; the rollup was never initialised';
    END IF;

    -- Committed queue hours first, and the ids this pass's
    -- snapshot actually saw: consumption below is by id, so a
    -- queue row committed while this pass is running survives
    -- for the next pass, which re-rolls its hour and sees both
    -- the rows behind it and (already) the re-roll this pass did.
    SELECT array_agg(DISTINCT bucket_hour), array_agg(id)
      INTO v_queued, v_queued_ids
      FROM log_entry_rollup_dirty_hours;

    SELECT COALESCE(array_agg(DISTINCT h), '{}')
      INTO v_hours
      FROM (
            SELECT generate_series(
                       LEAST(date_trunc('hour', le.timestamp_request),
                             date_trunc('hour', COALESCE(le.timestamp_forwarding,
                                                         le.timestamp_request,
                                                         le.timestamp_response))),
                       GREATEST(date_trunc('hour', le.timestamp_request),
                                date_trunc('hour', COALESCE(le.timestamp_forwarding,
                                                            le.timestamp_request,
                                                            le.timestamp_response))),
                       interval '1 hour') AS h
              FROM log_entry le
             WHERE le.updated_at > v_last
               AND le.updated_at <= v_cutoff
            UNION
            SELECT generate_series(date_trunc('hour', v_last), v_open - interval '1 hour',
                                   interval '1 hour')
            UNION
            SELECT unnest(v_queued)
           ) dirty
     WHERE h IS NOT NULL
       AND h < v_open;

    v_written := logos_stats_rollup_apply(v_hours);

    DELETE FROM log_entry_rollup_dirty_hours
     WHERE id = ANY (COALESCE(v_queued_ids, '{}'));

    UPDATE log_entry_rollup_state SET processed_through = v_cutoff;

    hours_rebuilt := COALESCE(array_length(v_hours, 1), 0);
    rows_written  := v_written;
    RETURN NEXT;
END;
$$;

