CREATE OR REPLACE FUNCTION logos_stats_rollup_pass(p_write_lag interval)
RETURNS TABLE (hours_rebuilt bigint, rows_written bigint)
LANGUAGE plpgsql
SET search_path = public, pg_catalog
AS $$
DECLARE
    v_last    timestamptz;
    v_cutoff  timestamptz := now() - p_write_lag;
    v_open    timestamptz := date_trunc('hour', now());
    v_hours   timestamptz[];
    v_written bigint;
BEGIN
    SELECT processed_through INTO v_last FROM log_entry_rollup_state;
    IF v_last IS NULL THEN
        RAISE EXCEPTION 'log_entry_rollup_state is empty; the rollup was never initialised';
    END IF;

    SELECT COALESCE(array_agg(DISTINCT h), '{}')
      INTO v_hours
      FROM (
            SELECT generate_series(
                       LEAST(date_trunc('hour', le.timestamp_request),
                             date_trunc('hour', COALESCE(le.timestamp_forwarding,
                                                         le.timestamp_request,
                                                         le.timestamp_response))),
                       GREATEST(date_trunc('hour', le.timestamp_request),
                                date_trunc('hour', COALESCE(le.timestamp_forwarding,
                                                            le.timestamp_request,
                                                            le.timestamp_response))),
                       interval '1 hour') AS h
              FROM log_entry le
             WHERE le.updated_at > v_last
               AND le.updated_at <= v_cutoff
            UNION
            SELECT generate_series(date_trunc('hour', v_last), v_open - interval '1 hour',
                                   interval '1 hour')
           ) dirty
     WHERE h IS NOT NULL
       AND h < v_open;

    v_written := logos_stats_rollup_apply(v_hours);

    UPDATE log_entry_rollup_state SET processed_through = v_cutoff;

    hours_rebuilt := COALESCE(array_length(v_hours, 1), 0);
    rows_written  := v_written;
    RETURN NEXT;
END;
$$;

